import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

/**
 * Logic Rendering Engine & Geometric Utilities
 * Handles all P5.js drawing commands and hitbox calculations.
 */
export class CircuitRenderer {

  // --- Geometric Helpers (Used for Drawing & Hit Testing) ---

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    const componentSide = c.icPortSide || (isInput ? 'right' : 'left');
    switch (componentSide) {
        case 'top': return 'bottom';
        case 'bottom': return 'top';
        case 'left': return 'right';
        case 'right': return 'left';
    }
    return 'left';
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const getSide = CircuitRenderer.getSide; // Alias for brevity

          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          // Count pins on each side to determine needed size
          const topCount = inputs.filter(c => getSide(c, true) === 'top').length + outputs.filter(c => getSide(c, false) === 'top').length;
          const bottomCount = inputs.filter(c => getSide(c, true) === 'bottom').length + outputs.filter(c => getSide(c, false) === 'bottom').length;
          const leftCount = inputs.filter(c => getSide(c, true) === 'left').length + outputs.filter(c => getSide(c, false) === 'left').length;
          const rightCount = inputs.filter(c => getSide(c, true) === 'right').length + outputs.filter(c => getSide(c, false) === 'right').length;

          const width = Math.max(2, Math.max(topCount, bottomCount) + 1);
          const height = Math.max(2, Math.max(leftCount, rightCount) + 1);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 2, h: 2, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    // 1. Dynamic pin positioning for IO components
    if ((comp.type === ComponentType.INPUT_SWITCH || comp.type === ComponentType.CLOCK) && type === 'output') {
        const side = comp.icPortSide || 'right';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    // 2. Custom IC Pin Logic
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
             const getSide = CircuitRenderer.getSide;

             // Helper to sort pins consistently
             const sortGroup = (list: CircuitComponent[], isInput: boolean) => {
                return list.sort((a, b) => {
                    const sideA = getSide(a, isInput);
                    const sideB = getSide(b, isInput);
                    if (sideOrder[sideA] !== sideOrder[sideB]) return sideOrder[sideA] - sideOrder[sideB];
                    if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                });
             };

             const targetGroup = type === 'input' 
                ? sortGroup(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true)
                : sortGroup(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

             const targetComp = targetGroup[index];
             if (targetComp) {
                 const side = getSide(targetComp, type === 'input');
                 const sideGroup = targetGroup.filter(c => getSide(c, type === 'input') === side);
                 const localIndex = sideGroup.indexOf(targetComp);
                 const count = sideGroup.length;

                 // Distribute pins evenly along the edge
                 if (side === 'top') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y, side: 'top' };
                 } else if (side === 'bottom') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y + h, side: 'bottom' };
                 } else if (side === 'left') {
                     const step = h / (count + 1);
                     return { x: comp.x, y: comp.y + ((localIndex + 1) * step), side: 'left' };
                 } else { // right
                     const step = h / (count + 1);
                     return { x: comp.x + w, y: comp.y + ((localIndex + 1) * step), side: 'right' };
                 }
             }
         }
    }

    // 3. Standard Gates (Distribute evenly on Left/Right)
    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Drawing Methods ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
        p.strokeWeight(wire.state ? 3 : 2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output' }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);

        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);

        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') {
             cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        } else {
             cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };
        }

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    const py = 6;
    const padX = 4;
    const effectiveH = h - (py * 2);

    p.push();
    p.translate(comp.x, comp.y);

    // Body Style
    p.fill(COLOR_COMPONENT_BG);
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);

    // Dispatcher for Specific Component Rendering
    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h, padX, py, effectiveH);
    } else if (comp.type === ComponentType.CLOCK) {
        CircuitRenderer.drawClock(p, comp, w, h, padX, py, effectiveH);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h, padX);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, effectiveH, padX, py);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h, py, effectiveH);
    }

    // Custom Label Rendering
    CircuitRenderer.drawLabels(p, comp, w, h);

    // Standard Ports (Points)
    if (comp.type !== ComponentType.CUSTOM_IC && comp.type !== ComponentType.INPUT_SWITCH && comp.type !== ComponentType.OUTPUT_LED && comp.type !== ComponentType.CLOCK) {
        p.noStroke();
        p.fill('#64748b');
        for (let i = 0; i < inputs; i++) {
           const y = ((i + 1) * (h / (inputs + 1)));
           p.circle(0, y, 4);
        }
        for (let i = 0; i < outputs; i++) {
           const y = ((i + 1) * (h / (outputs + 1)));
           p.circle(w, y, 4);
        }
    }

    // Selection Highlight
    if (isSelected) {
        p.noFill();
        p.stroke('#3b82f6');
        p.strokeWeight(2);
        p.rect(-padX, -padX, w + (padX*2), h + (padX*2), 4);
    }

    p.pop();
  }

  // --- Sub-Renderers ---

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.rect(0, 0, w, h, 4);
    p.fill('#1e293b');
    p.noStroke();
    p.textSize(12);
    p.textStyle(p.BOLD);
    p.textAlign(p.CENTER, p.CENTER);
    p.text(comp.customLabel || "IC", w/2, h/2);

    // Draw small pins visual
    const funcDef = library.find(f => f.id === comp.functionId);
    if (funcDef) {
        p.textSize(8);
        p.textStyle(p.NORMAL);
        const drawPin = (c: CircuitComponent, isInput: boolean) => {
            const side = CircuitRenderer.getSide(c, isInput);
            // Re-calculate sorting for drawing labels correctly
            const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
            const sorter = (a: CircuitComponent, b: CircuitComponent) => {
                 if (sideOrder[CircuitRenderer.getSide(a, isInput)] !== sideOrder[CircuitRenderer.getSide(b, isInput)]) return 0;
                 const sa = CircuitRenderer.getSide(a, isInput);
                 if (sa === 'top' || sa === 'bottom') return a.x - b.x;
                 return a.y - b.y;
            };

            const group = isInput 
               ? funcDef.components.filter(x => x.type === ComponentType.INPUT_SWITCH).sort(sorter)
               : funcDef.components.filter(x => x.type === ComponentType.OUTPUT_LED).sort(sorter);

            const sideGroup = group.filter(x => CircuitRenderer.getSide(x, isInput) === side);
            const localIndex = sideGroup.indexOf(c);
            const count = sideGroup.length;

            let px = 0, py = 0;
            p.fill('#64748b');
            if (side === 'top') {
                px = (localIndex + 1) * (w / (count + 1));
                py = 0;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.TOP);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, 6);
            } else if (side === 'bottom') {
                px = (localIndex + 1) * (w / (count + 1));
                py = h;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.BOTTOM);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, h - 6);
            } else if (side === 'left') {
                px = 0;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.LEFT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), 6, py);
            } else {
                px = w;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.RIGHT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), w - 6, py);
            }
        };
        funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH).forEach(c => drawPin(c, true));
        funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED).forEach(c => drawPin(c, false));
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number, py: number, effectiveH: number) {
    const isOn = comp.outputValues[0];
    const side = comp.icPortSide || 'right';

    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    let portX = 0, portY = 0;

    if (side === 'right') { p.line(w - padX, h/2, w, h/2); portX = w; portY = h/2; }
    else if (side === 'left') { p.line(0, h/2, padX, h/2); portX = 0; portY = h/2; }
    else if (side === 'top') { p.line(w/2, 0, w/2, padX); portX = w/2; portY = 0; }
    else if (side === 'bottom') { p.line(w/2, h - padX, w/2, h); portX = w/2; portY = h; }

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);
    p.rect(padX, py, w - (padX*2), effectiveH, 4); 

    p.noStroke();
    p.fill(isOn ? '#fff' : '#475569');
    p.textSize(9);
    p.push();
    p.translate(w/2, h/2);
    if (side === 'top' || side === 'bottom') p.rotate(-p.HALF_PI);
    p.text(isOn ? "ON" : "OFF", 0, 0);
    p.pop();

    p.fill(isOn ? '#fff' : '#94a3b8');
    const arrowDist = 12;
    if (side === 'right') CircuitRenderer.drawArrow(p, w - arrowDist, h/2, 'right', 6);
    else if (side === 'left') CircuitRenderer.drawArrow(p, arrowDist, h/2, 'left', 6);
    else if (side === 'top') CircuitRenderer.drawArrow(p, w/2, arrowDist, 'top', 6);
    else if (side === 'bottom') CircuitRenderer.drawArrow(p, w/2, h - arrowDist, 'bottom', 6);
  }

  private static drawClock(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number, py: number, effectiveH: number) {
    const side = comp.icPortSide || 'right';
    p.stroke(COLOR_COMPONENT_STROKE);
    let portX = 0, portY = 0;
    if (side === 'right') { p.line(w - padX, h/2, w, h/2); portX = w; portY = h/2; }
    else if (side === 'left') { p.line(0, h/2, padX, h/2); portX = 0; portY = h/2; }
    else if (side === 'top') { p.line(w/2, 0, w/2, padX); portX = w/2; portY = 0; }
    else if (side === 'bottom') { p.line(w/2, h - padX, w/2, h); portX = w/2; portY = h; }

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    const isOn = comp.outputValues[0];
    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.fill(COLOR_COMPONENT_BG);
    p.rect(padX, py, w - (padX*2), effectiveH, 4);

    p.noFill();
    p.stroke(isOn ? COLOR_WIRE_ON : '#64748b');
    p.strokeWeight(2);
    const cw = w - (padX*2);
    const cx = padX + cw/2;
    const cy = py + effectiveH/2;

    p.beginShape();
    p.vertex(cx - 8, cy + 4);
    p.vertex(cx - 4, cy + 4);
    p.vertex(cx - 4, cy - 4);
    p.vertex(cx + 4, cy - 4);
    p.vertex(cx + 4, cy + 4);
    p.vertex(cx + 8, cy + 4);
    p.endShape();
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number) {
    const isOn = comp.inputValues[0];
    const side = comp.icPortSide || 'left';

    p.stroke(COLOR_COMPONENT_STROKE);
    let portX = 0, portY = 0;
    if (side === 'right') { p.line(w - padX, h/2, w, h/2); portX = w; portY = h/2; }
    else if (side === 'left') { p.line(0, h/2, padX, h/2); portX = 0; portY = h/2; }
    else if (side === 'top') { p.line(w/2, 0, w/2, padX); portX = w/2; portY = 0; }
    else if (side === 'bottom') { p.line(w/2, h - padX, w/2, h); portX = w/2; portY = h; }

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    p.noStroke();
    const r = (Math.min(w, h) - (padX * 2)) / 2;
    if (isOn) {
        p.fill(245, 158, 11, 80); 
        p.circle(w/2, h/2, r * 2.5);
    }
    p.fill(isOn ? COLOR_WIRE_ON : '#334155');
    p.circle(w/2, h/2, r * 2);

    p.fill('#fff');
    const arrowDist = 10;
    if (side === 'right') CircuitRenderer.drawArrow(p, w - arrowDist, h/2, 'left', 4);
    else if (side === 'left') CircuitRenderer.drawArrow(p, arrowDist, h/2, 'right', 4);
    else if (side === 'top') CircuitRenderer.drawArrow(p, w/2, arrowDist, 'bottom', 4);
    else if (side === 'bottom') CircuitRenderer.drawArrow(p, w/2, h - arrowDist, 'top', 4);
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, effectiveH: number, padX: number, py: number) {
    const h = effectiveH + (py * 2); // approximate
    const yStep = h / 5;
    for(let i=0; i<4; i++) p.line(0, (i+1) * yStep, padX, (i+1) * yStep);
    p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, py, w - (padX*2), effectiveH, 4);
    p.noStroke(); p.fill('#ef4444'); p.textSize(16);
    let val = 0;
    if(comp.inputValues[0]) val += 1; if(comp.inputValues[1]) val += 2;
    if(comp.inputValues[2]) val += 4; if(comp.inputValues[3]) val += 8;
    p.text(val.toString(16).toUpperCase(), w/2, h/2 + 1);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number, py: number, effectiveH: number) {
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = w;
    if (isNegated) bodyW = w - (bubbleR*2) - 2;

    if (comp.type === 'AND' || comp.type === 'NAND') {
        p.beginShape(); p.vertex(0, py); p.vertex(bodyW * 0.5, py);
        (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py); p.vertex(0, h - py); p.endShape(p.CLOSE);
    } else if (comp.type === 'NOT') {
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
    } else if (comp.type === 'OR' || comp.type === 'NOR') {
        p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(5, h * 0.25, 5, h * 0.75, 0, h - py);
        (p as any).bezierVertex(w * 0.5, h - py, bodyW, h/2 + (effectiveH/4), bodyW, h/2);
        (p as any).bezierVertex(bodyW, h/2 - (effectiveH/4), w * 0.5, py, 0, py); p.endShape(p.CLOSE);
    } else if (comp.type === 'XOR') {
       p.noFill(); p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(5, h * 0.25, 5, h * 0.75, 0, h - py); p.endShape();
       p.fill(COLOR_COMPONENT_BG); p.beginShape(); p.vertex(4, py); (p as any).bezierVertex(9, h * 0.25, 9, h * 0.75, 4, h - py);
       (p as any).bezierVertex((w * 0.5) + 4, h - py, bodyW, h/2 + (effectiveH/4), bodyW, h/2);
       (p as any).bezierVertex(bodyW, h/2 - (effectiveH/4), (w * 0.5) + 4, py, 4, py); p.endShape(p.CLOSE);
    }
    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE);
        p.circle(w - bubbleR - 1, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke();
        p.fill('#1e293b');
        p.textSize(12);
        p.textStyle(p.BOLD);

        if (comp.type === ComponentType.INPUT_SWITCH || comp.type === ComponentType.CLOCK) {
           const side = comp.icPortSide || 'right';
           if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else if (comp.type === ComponentType.OUTPUT_LED) {
           const side = comp.icPortSide || 'left';
           if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else {
           p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        }
        p.textAlign(p.CENTER, p.CENTER);
        p.textStyle(p.NORMAL);
      }
  }

  private static drawArrow(p: p5Types, x: number, y: number, side: PortSide, size: number) {
    p.push();
    p.translate(x, y);
    if (side === 'right') p.rotate(0);
    else if (side === 'bottom') p.rotate(p.HALF_PI);
    else if (side === 'left') p.rotate(p.PI);
    else if (side === 'top') p.rotate(-p.HALF_PI);

    p.triangle(-size, -size/2, 0, 0, -size, size/2);
    p.pop();
  }
}

import { useState, useRef, useEffect, useLayoutEffect } from 'react';
import { FunctionCircuit, CircuitComponent, Wire } from '../types';
import { LogicCanvasHandle } from '../components/LogicCanvas';

const LOCAL_STORAGE_KEY = 'logicflow_autosave_v1';
const LOCAL_STORAGE_ID_KEY = 'logicflow_active_id_v1';

export const useProjectManager = (canvasRef: React.RefObject<LogicCanvasHandle | null>) => {
  // -- State --
  const [functions, setFunctions] = useState<FunctionCircuit[]>(() => {
    try {
      const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      }
    } catch (e) { console.error(e); }
    return [{ id: 'main', name: 'Main Circuit', components: [], wires: [] }];
  });

  const [activeFunctionId, setActiveFunctionId] = useState<string>(() => {
    try {
        const savedId = localStorage.getItem(LOCAL_STORAGE_ID_KEY);
        if (savedId) return savedId;
    } catch(e) {}
    return 'main';
  });

  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [dataVersion, setDataVersion] = useState(0); // Used to force-refresh canvas on bulk updates

  // Refs for autosave callback access
  const functionsRef = useRef(functions);
  const activeIdRef = useRef(activeFunctionId);
  useEffect(() => { functionsRef.current = functions; }, [functions]);
  useEffect(() => { activeIdRef.current = activeFunctionId; }, [activeFunctionId]);

  // -- Validation --
  useLayoutEffect(() => {
    if (!functions.find(f => f.id === activeFunctionId)) {
        setActiveFunctionId(functions[0]?.id || 'main');
    }
  }, [functions, activeFunctionId]);

  // -- Helpers --
  const getLatestFunctionsState = (): FunctionCircuit[] => {
    let currentData = functionsRef.current;
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        currentData = currentData.map(f => 
            f.id === activeIdRef.current 
              ? { ...f, components: [...components], wires: [...wires] } 
              : f
        );
    }
    return currentData;
  };

  const persist = () => {
    const data = getLatestFunctionsState();
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, activeIdRef.current);
        setLastSaved(new Date());
    } catch (e) { console.error("Save failed", e); }
    // Optimistic update of local state if needed, but usually we just sync refs
    // setFunctions(data); 
  };

  // -- Autosave Effect --
  useEffect(() => {
    const interval = setInterval(persist, 5000);
    const handleVis = () => { if (document.hidden) persist(); };
    const handleUnload = () => { persist(); };

    document.addEventListener("visibilitychange", handleVis);
    window.addEventListener("beforeunload", handleUnload);

    return () => {
        clearInterval(interval);
        document.removeEventListener("visibilitychange", handleVis);
        window.removeEventListener("beforeunload", handleUnload);
        persist();
    };
  }, []);

  // -- Actions --

  const syncCanvasToState = () => {
      const updated = getLatestFunctionsState();
      setFunctions(updated);
      return updated;
  };

  const switchToFunction = (id: string) => {
    if (id === activeFunctionId) return;
    syncCanvasToState();
    setActiveFunctionId(id);
  };

  const addFunction = (name: string) => {
    const current = syncCanvasToState();
    const newId = crypto.randomUUID();
    const newFunc: FunctionCircuit = { id: newId, name, components: [], wires: [] };
    const next = [...current, newFunc];
    setFunctions(next);
    setActiveFunctionId(newId);
    persist();
  };

  const deleteFunction = (id: string) => {
    if (id === 'main') return;
    const next = functions.filter(f => f.id !== id);
    setFunctions(next);
    if (activeFunctionId === id) setActiveFunctionId('main');
    persist();
  };

  const importData = (data: any, isFullProject: boolean) => {
      if (isFullProject) {
        setFunctions(data);
        setActiveFunctionId(data[0].id);
        setDataVersion(v => v + 1);
      } else {
        const current = getLatestFunctionsState();
        setFunctions([...current, data]);
      }
      persist();
  };

  const clearData = () => {
    localStorage.removeItem(LOCAL_STORAGE_KEY);
    localStorage.removeItem(LOCAL_STORAGE_ID_KEY);
    setFunctions([{ id: 'main', name: 'Main Circuit', components: [], wires: [] }]);
    setActiveFunctionId('main');
    setDataVersion(v => v + 1);
  };

  return {
      functions,
      activeFunctionId,
      activeFunction: functions.find(f => f.id === activeFunctionId) || functions[0],
      lastSaved,
      dataVersion,
      getLatestFunctionsState,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist // Quick save
  };
};

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- Simulation State --
  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  // -- Selection & Interaction State --
  const selectedCompId = useRef<string | null>(null);
  const activeDragId = useRef<string | null>(null);

  // -- Viewport / Camera State --
  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);

  // -- Interaction State --
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 }); 
  const accumulatorRef = useRef<number>(0);

  // -- Refs for Props --
  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  // -- Expose API --
  useImperativeHandle(ref, () => ({
    getData: () => ({
        components: componentsRef.current,
        wires: wiresRef.current
    }),
    updateSelectedComponent: (updates: Partial<CircuitComponent>) => {
        if (selectedCompId.current) {
            const comp = componentsRef.current.find(c => c.id === selectedCompId.current);
            if (comp) Object.assign(comp, updates);
        }
    },
    deleteSelected: () => {
        if (selectedCompId.current) {
             const id = selectedCompId.current;
             componentsRef.current = componentsRef.current.filter(c => c.id !== id);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== id && w.toCompId !== id);
             selectedCompId.current = null;
             activeDragId.current = null;
             if(onSelectionChange) onSelectionChange(null);
        }
    }
  }));

  const screenToWorld = (sx: number, sy: number): Point => {
    return {
      x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
      y: (sy - viewportRef.current.y) / viewportRef.current.zoom
    };
  };

  // -- Component Management --
  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;

    // Logic to init specific component properties
    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs;
    outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            internalState = {
                components: JSON.parse(JSON.stringify(func.components)),
                wires: JSON.parse(JSON.stringify(func.wires))
            };
        }
    }

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(inputsCount).fill(false),
      outputValues: new Array(outputsCount).fill(false),
      functionId: functionId,
      internalState: internalState,
      customLabel: type === ComponentType.CUSTOM_IC ? label : undefined
    };

    componentsRef.current.push(newComp);
    selectedCompId.current = newComp.id;
    if (onSelectionChange) onSelectionChange(newComp);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  // -- P5 Setup --
  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0;
      let lastTouchY = 0;
      let isCanvasInteraction = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        p.textSize(10);
        p.textAlign(p.CENTER, p.CENTER);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => {
        if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight);
      };

      p.draw = () => {
        p.background(COLOR_BG);

        // Simulation Step
        if (isPlayingRef.current) {
          accumulatorRef.current += p.deltaTime;
          if (accumulatorRef.current > 500) accumulatorRef.current = 500;
          const speed = tickSpeedRef.current;
          while (accumulatorRef.current >= speed) {
            const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
            componentsRef.current = result.components;
            wiresRef.current = result.wires;
            accumulatorRef.current -= speed;
          }
        } else {
          accumulatorRef.current = 0;
        }

        // Render
        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        // 1. Grid
        CircuitRenderer.drawGrid(p, viewportRef.current);

        // 2. Wires
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        // 3. Draft Wire
        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        // 4. Components
        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, comp.id === selectedCompId.current);
        });

        // 5. Port Highlights (Hover)
        if (!wiringStart.current && !activeDragId.current) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);
                    p.noFill();
                    p.stroke('#3b82f6'); 
                    p.strokeWeight(2);
                    p.circle(pos.x, pos.y, 14);
                }
            }
        }

        p.pop();
      };

      // -- Hit Testing Utils (Scoped to Sketch) --
      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- Interaction Handlers --

      const updateComponentPos = (sx: number, sy: number) => {
          isDraggingComp.current = true;
          const mouseWorld = screenToWorld(sx, sy);
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp) {
            comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
            comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
          }
      };

      // Touch Logic
      (p as any).touchStarted = (e: any) => {
        if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; }
        isCanvasInteraction = true;
        if (p.touches.length === 2) {
          const t0 = p.touches[0] as any, t1 = p.touches[1] as any;
          // @ts-ignore
          pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y);
        } else if (p.touches.length === 1) {
          const t0 = p.touches[0] as any;
          lastTouchX = t0.x; lastTouchY = t0.y;
          p.mousePressed(undefined); 
        }
        return false;
      };

      (p as any).touchMoved = (e: any) => {
        if (!isCanvasInteraction) return true;
        if (p.touches.length === 2) {
          const t0 = p.touches[0] as any, t1 = p.touches[1] as any;
          // @ts-ignore
          const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y);
          if (pinchDistStart > 0) {
            const scaleFactor = currentDist / pinchDistStart;
            const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0);
            // @ts-ignore
            const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2;
            const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom;
            const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom;
            viewportRef.current.x = cx - wx * newZoom;
            viewportRef.current.y = cy - wy * newZoom;
            viewportRef.current.zoom = newZoom;
            pinchDistStart = currentDist;
          }
        } else if (p.touches.length === 1) {
          const t0 = p.touches[0] as any;
          if (activeDragId.current) updateComponentPos(t0.x, t0.y);
          else if (isPanningRef.current) {
            viewportRef.current.x += (t0.x - lastTouchX);
            viewportRef.current.y += (t0.y - lastTouchY);
          }
          lastTouchX = t0.x; lastTouchY = t0.y;
        }
        return false;
      };

      (p as any).touchEnded = () => {
        if (!isCanvasInteraction) return true;
        if (p.touches.length === 0) p.mouseReleased();
        return false;
      };

      (p as any).mouseWheel = (e: any) => {
        const zoomFactor = Math.exp(-e.delta * 0.001);
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0);
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom;
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom;
        viewportRef.current.zoom = newZoom;
        viewportRef.current.x = p.mouseX - wx * newZoom;
        viewportRef.current.y = p.mouseY - wy * newZoom;
        return false;
      };

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;
        if (p.mouseX < 0 || p.mouseX > p.width || p.mouseY < 0 || p.mouseY > p.height) return;

        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
        isDraggingComp.current = false;
        isPanningRef.current = false;

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            // Detach Logic
            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output' };
                    return;
                }
            }
          wiringStart.current = port;
          return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
          if (toolRef.current === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             if (selectedCompId.current === compId && onSelectionChange) onSelectionChange(null);
             if (activeDragId.current === compId) activeDragId.current = null;
             return;
          }
          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             selectedCompId.current = compId;
             activeDragId.current = compId;
             dragOffset.current = { x: mouseWorld.x - comp.x, y: mouseWorld.y - comp.y };
             if (onSelectionChange) onSelectionChange(comp);
          }
          return;
        }

        selectedCompId.current = null;
        activeDragId.current = null;
        if (onSelectionChange) onSelectionChange(null);
        isPanningRef.current = true;
      };

      p.mouseDragged = () => {
        if (p.touches.length > 0) return;
        if (isPanningRef.current) {
          viewportRef.current.x += (p.mouseX - p.pmouseX);
          viewportRef.current.y += (p.mouseY - p.pmouseY);
        } else if (activeDragId.current) {
           updateComponentPos(p.mouseX, p.mouseY);
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Click Interaction (Toggle Switch)
        if (activeDragId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
              comp.outputValues[0] = !comp.outputValues[0];
          }
        }

        activeDragId.current = null;
        isDraggingComp.current = false;
        isPanningRef.current = false;

        // Finalize Wire
        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
            let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
            let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

            if (src.type === 'output' && dst.type === 'input') {
              const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
              if (!exists) {
                wiresRef.current.push({
                  id: crypto.randomUUID(),
                  fromCompId: src.compId,
                  fromPortIndex: src.portIndex,
                  toCompId: dst.compId,
                  toPortIndex: dst.portIndex,
                  state: false
                });
              }
            }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); // Re-init if wrapper changes, but data is kept in refs

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    />
  );
});

export default LogicCanvas;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import { ComponentType, CircuitComponent, FunctionCircuit } from './types';
import { COMPONENT_DEFINITIONS } from './constants';
import { useProjectManager } from './hooks/useProjectManager';

const App: React.FC = () => {
  // -- UI State --
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false);
  const [tickSpeed, setTickSpeed] = useState(50); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);

  // -- Component Selection State --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  // -- Drag State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string} | null>(null);

  // -- References --
  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // -- Project Data Management --
  const {
      functions,
      activeFunctionId,
      activeFunction,
      lastSaved,
      dataVersion,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  } = useProjectManager(canvasRef);

  // -- Interactions --

  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent, functionId?: string) => {
    const touch = e.touches[0];
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left && dragPos.x <= rect.right &&
          dragPos.y >= rect.top && dragPos.y <= rect.bottom
        ) {
          setPendingDrop({ type: draggedType, x: dragPos.x - rect.left, y: dragPos.y - rect.top, functionId: draggedFuncId });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos, draggedFuncId]);

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            if (Array.isArray(parsed)) {
                if (confirm("Replace current project?")) {
                    importData(parsed, true);
                    setSelectedComponent(null);
                    setIsPlaying(false);
                }
            } else if (parsed.id) {
                importData(parsed, false);
                alert(`Imported: ${parsed.name}`);
            }
        } catch (err) { alert("Invalid File"); }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const handleExport = (type: 'PROJECT' | 'FUNCTION') => {
      const data = type === 'PROJECT' 
        ? functions.map(f => f.id === activeFunctionId && canvasRef.current ? {...f, ...canvasRef.current.getData()} : f)
        : (canvasRef.current ? {...activeFunction, ...canvasRef.current.getData()} : activeFunction);

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = type === 'PROJECT' ? `project.json` : `${activeFunction.name.replace(/\s+/g, '_')}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setIsProjectMenuOpen(false);
  };

  const createFunction = (e: React.FormEvent) => {
      e.preventDefault();
      if (newFuncName.trim()) {
          addFunction(newFuncName);
          setNewFuncName("");
          setIsModalOpen(false);
      }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) setTempLabel(comp.customLabel || "");
      else setTempLabel("");
  };

  const updateProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">
        {/* HUD */}
        <div className="absolute top-4 left-4 right-4 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap items-center justify-between px-4 py-2 z-10 border border-slate-200 gap-2">

          <div className="flex items-center space-x-2">
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => { setIsPlaying(false); switchToFunction(e.target.value); }}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
               </select>
               <button onClick={() => setIsModalOpen(true)} className="ml-2 w-8 h-8 bg-blue-100 text-blue-600 rounded hover:bg-blue-200 font-bold">+</button>
               {activeFunctionId !== 'main' && (
                 <button onClick={() => deleteFunction(activeFunctionId)} className="ml-1 w-8 h-8 bg-red-100 text-red-500 rounded hover:bg-red-200 font-bold">×</button>
               )}
             </div>

             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded text-sm font-semibold text-slate-700 w-24"
             >
               {isPlaying ? 'Pause' : 'Resume'}
             </button>

             <div className="relative">
                <button onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)} className="px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700">
                    Project ▼
                </button>
                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                        <div className="px-4 py-2 text-xs text-slate-400 border-b mb-1">
                            {lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Unsaved'}
                        </div>
                        <button onClick={() => { persist(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">💾 Save Now</button>
                        <button onClick={() => { fileInputRef.current?.click(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📂 Import...</button>
                        <button onClick={() => handleExport('PROJECT')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📦 Export All</button>
                        <button onClick={() => handleExport('FUNCTION')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📄 Export Active</button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={() => { if(confirm("Clear all data?")) clearData(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50">🗑️ Reset</button>
                    </div>
                )}
                {isProjectMenuOpen && <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>}
             </div>
          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end">
             {selectedComponent && (
                 <div className="flex items-center space-x-2 flex-1 md:flex-none justify-center">
                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <input 
                            type="text" 
                            value={tempLabel}
                            onChange={(e) => { setTempLabel(e.target.value); updateProp({ customLabel: e.target.value }); }}
                            className="bg-white border border-yellow-200 text-sm px-2 py-1 rounded w-24 focus:outline-none"
                            placeholder="Label"
                        />
                     </div>
                     {['INPUT','OUTPUT','CLOCK'].includes(selectedComponent.type) && (
                         <select 
                             value={selectedComponent.icPortSide || (selectedComponent.type === 'OUTPUT' ? 'left' : 'right')}
                             onChange={(e) => updateProp({ icPortSide: e.target.value as any })}
                             className="bg-white border border-blue-200 text-sm px-2 py-1 rounded focus:outline-none"
                         >
                             <option value="top">Top</option>
                             <option value="bottom">Bottom</option>
                             <option value="left">Left</option>
                             <option value="right">Right</option>
                         </select>
                     )}
                 </div>
             )}
            <input type="range" min="5" max="500" value={tickSpeed} onChange={(e) => setTickSpeed(Number(e.target.value))} className="w-24 accent-slate-900" />
          </div>
        </div>

        {/* Canvas */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={() => setPendingDrop(null)}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Drag Ghost */}
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-80" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">{draggedType === 'IC' ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}</span>
            </div>
          </div>
        )}

        {/* Modal */}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100"><h3 className="font-bold">New Function</h3></div>
              <form onSubmit={createFunction} className="p-4">
                <input autoFocus type="text" value={newFuncName} onChange={(e) => setNewFuncName(e.target.value)} placeholder="Function Name" className="w-full px-3 py-2 border rounded-lg mb-4" />
                <div className="flex justify-end space-x-2">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-bold text-slate-500">Cancel</button>
                  <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg">Create</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

/**
 * Logic Rendering Engine & Geometric Utilities
 * Handles all P5.js drawing commands and hitbox calculations.
 */
export class CircuitRenderer {

  // --- Geometric Helpers (Used for Drawing & Hit Testing) ---

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    const componentSide = c.icPortSide || (isInput ? 'right' : 'left');
    switch (componentSide) {
        case 'top': return 'bottom';
        case 'bottom': return 'top';
        case 'left': return 'right';
        case 'right': return 'left';
    }
    return 'left';
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const getSide = CircuitRenderer.getSide; // Alias for brevity

          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          // Count pins on each side to determine needed size
          const topCount = inputs.filter(c => getSide(c, true) === 'top').length + outputs.filter(c => getSide(c, false) === 'top').length;
          const bottomCount = inputs.filter(c => getSide(c, true) === 'bottom').length + outputs.filter(c => getSide(c, false) === 'bottom').length;
          const leftCount = inputs.filter(c => getSide(c, true) === 'left').length + outputs.filter(c => getSide(c, false) === 'left').length;
          const rightCount = inputs.filter(c => getSide(c, true) === 'right').length + outputs.filter(c => getSide(c, false) === 'right').length;

          const width = Math.max(2, Math.max(topCount, bottomCount) + 1);
          const height = Math.max(2, Math.max(leftCount, rightCount) + 1);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 2, h: 2, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    // 1. Dynamic pin positioning for IO components
    if ((comp.type === ComponentType.INPUT_SWITCH || comp.type === ComponentType.CLOCK) && type === 'output') {
        const side = comp.icPortSide || 'right';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    // 2. Custom IC Pin Logic
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
             const getSide = CircuitRenderer.getSide;

             // Helper to sort pins consistently
             const sortGroup = (list: CircuitComponent[], isInput: boolean) => {
                return list.sort((a, b) => {
                    const sideA = getSide(a, isInput);
                    const sideB = getSide(b, isInput);
                    if (sideOrder[sideA] !== sideOrder[sideB]) return sideOrder[sideA] - sideOrder[sideB];
                    if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                });
             };

             const targetGroup = type === 'input' 
                ? sortGroup(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true)
                : sortGroup(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

             const targetComp = targetGroup[index];
             if (targetComp) {
                 const side = getSide(targetComp, type === 'input');
                 const sideGroup = targetGroup.filter(c => getSide(c, type === 'input') === side);
                 const localIndex = sideGroup.indexOf(targetComp);
                 const count = sideGroup.length;

                 // Distribute pins evenly along the edge
                 if (side === 'top') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y, side: 'top' };
                 } else if (side === 'bottom') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y + h, side: 'bottom' };
                 } else if (side === 'left') {
                     const step = h / (count + 1);
                     return { x: comp.x, y: comp.y + ((localIndex + 1) * step), side: 'left' };
                 } else { // right
                     const step = h / (count + 1);
                     return { x: comp.x + w, y: comp.y + ((localIndex + 1) * step), side: 'right' };
                 }
             }
         }
    }

    // 3. Standard Gates (Distribute evenly on Left/Right)
    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Drawing Methods ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
        p.strokeWeight(wire.state ? 3 : 2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output' }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);

        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);

        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') {
             cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        } else {
             cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };
        }

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    const py = 6;
    const padX = 4;
    const effectiveH = h - (py * 2);

    p.push();
    p.translate(comp.x, comp.y);

    // Body Style
    p.fill(COLOR_COMPONENT_BG);
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);

    // Dispatcher for Specific Component Rendering
    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h, padX, py, effectiveH);
    } else if (comp.type === ComponentType.CLOCK) {
        CircuitRenderer.drawClock(p, comp, w, h, padX, py, effectiveH);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h, padX);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, effectiveH, padX, py);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h, py, effectiveH);
    }

    // Custom Label Rendering
    CircuitRenderer.drawLabels(p, comp, w, h);

    // Standard Ports (Points)
    if (comp.type !== ComponentType.CUSTOM_IC && comp.type !== ComponentType.INPUT_SWITCH && comp.type !== ComponentType.OUTPUT_LED && comp.type !== ComponentType.CLOCK) {
        p.noStroke();
        p.fill('#64748b');
        for (let i = 0; i < inputs; i++) {
           const y = ((i + 1) * (h / (inputs + 1)));
           p.circle(0, y, 4);
        }
        for (let i = 0; i < outputs; i++) {
           const y = ((i + 1) * (h / (outputs + 1)));
           p.circle(w, y, 4);
        }
    }

    // Selection Highlight
    if (isSelected) {
        p.noFill();
        p.stroke('#3b82f6');
        p.strokeWeight(2);
        p.rect(-padX, -padX, w + (padX*2), h + (padX*2), 4);
    }

    p.pop();
  }

  // --- Sub-Renderers ---

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.rect(0, 0, w, h, 4);
    p.fill('#1e293b');
    p.noStroke();
    p.textSize(12);
    p.textStyle(p.BOLD);
    p.textAlign(p.CENTER, p.CENTER);
    p.text(comp.customLabel || "IC", w/2, h/2);

    // Draw small pins visual
    const funcDef = library.find(f => f.id === comp.functionId);
    if (funcDef) {
        p.textSize(8);
        p.textStyle(p.NORMAL);
        const drawPin = (c: CircuitComponent, isInput: boolean) => {
            const side = CircuitRenderer.getSide(c, isInput);
            // Re-calculate sorting for drawing labels correctly
            const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
            const sorter = (a: CircuitComponent, b: CircuitComponent) => {
                 if (sideOrder[CircuitRenderer.getSide(a, isInput)] !== sideOrder[CircuitRenderer.getSide(b, isInput)]) return 0;
                 const sa = CircuitRenderer.getSide(a, isInput);
                 if (sa === 'top' || sa === 'bottom') return a.x - b.x;
                 return a.y - b.y;
            };

            const group = isInput 
               ? funcDef.components.filter(x => x.type === ComponentType.INPUT_SWITCH).sort(sorter)
               : funcDef.components.filter(x => x.type === ComponentType.OUTPUT_LED).sort(sorter);

            const sideGroup = group.filter(x => CircuitRenderer.getSide(x, isInput) === side);
            const localIndex = sideGroup.indexOf(c);
            const count = sideGroup.length;

            let px = 0, py = 0;
            p.fill('#64748b');
            if (side === 'top') {
                px = (localIndex + 1) * (w / (count + 1));
                py = 0;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.TOP);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, 6);
            } else if (side === 'bottom') {
                px = (localIndex + 1) * (w / (count + 1));
                py = h;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.BOTTOM);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, h - 6);
            } else if (side === 'left') {
                px = 0;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.LEFT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), 6, py);
            } else {
                px = w;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.RIGHT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), w - 6, py);
            }
        };
        funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH).forEach(c => drawPin(c, true));
        funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED).forEach(c => drawPin(c, false));
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number, py: number, effectiveH: number) {
    const isOn = comp.outputValues[0];
    const side = comp.icPortSide || 'right';

    // Box Visuals
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;

    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    // Wire connection to port
    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    // Port Node
    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    // Body (Small Square)
    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4); 

    // Label
    p.noStroke();
    p.fill(isOn ? '#fff' : '#475569');
    p.textSize(10);
    p.textStyle(p.BOLD);
    p.textAlign(p.CENTER, p.CENTER);
    p.text(isOn ? "1" : "0", w/2, h/2);
    p.textStyle(p.NORMAL);
  }

  private static drawClock(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number, py: number, effectiveH: number) {
    // Clock uses similar layout to Switch but with different symbol
    const side = comp.icPortSide || 'right';

    // Box Visuals
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;
    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    // Connection
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    const isOn = comp.outputValues[0];
    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.fill(COLOR_COMPONENT_BG);
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

    // Clock Pulse Icon
    p.noFill();
    p.stroke(isOn ? COLOR_WIRE_ON : '#64748b');
    p.strokeWeight(2);
    const cx = w/2;
    const cy = h/2;

    p.beginShape();
    p.vertex(cx - 6, cy + 3);
    p.vertex(cx - 3, cy + 3);
    p.vertex(cx - 3, cy - 3);
    p.vertex(cx + 3, cy - 3);
    p.vertex(cx + 3, cy + 3);
    p.vertex(cx + 6, cy + 3);
    p.endShape();
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number) {
    const isOn = comp.inputValues[0];
    const side = comp.icPortSide || 'left';

    // Box Visuals
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;
    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    // Connection
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    // Body (Small Square)
    if (isOn) {
        p.noStroke();
        p.fill(245, 158, 11, 80); // Glow
        p.rect(boxOffset - 3, boxOffset - 3, boxSize + 6, boxSize + 6, 6);
    }

    p.stroke(isOn ? COLOR_WIRE_ON : '#334155');
    p.fill(isOn ? COLOR_WIRE_ON : '#1e293b');
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, effectiveH: number, padX: number, py: number) {
    const h = effectiveH + (py * 2); // approximate
    const yStep = h / 5;
    for(let i=0; i<4; i++) p.line(0, (i+1) * yStep, padX, (i+1) * yStep);
    p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, py, w - (padX*2), effectiveH, 4);
    p.noStroke(); p.fill('#ef4444'); p.textSize(16);
    let val = 0;
    if(comp.inputValues[0]) val += 1; if(comp.inputValues[1]) val += 2;
    if(comp.inputValues[2]) val += 4; if(comp.inputValues[3]) val += 8;
    p.text(val.toString(16).toUpperCase(), w/2, h/2 + 1);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number, py: number, effectiveH: number) {
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = w;
    if (isNegated) bodyW = w - (bubbleR*2) - 2;

    if (comp.type === 'AND' || comp.type === 'NAND') {
        p.beginShape(); p.vertex(0, py); p.vertex(bodyW * 0.5, py);
        (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py); p.vertex(0, h - py); p.endShape(p.CLOSE);
    } else if (comp.type === 'NOT') {
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
    } else if (comp.type === 'OR' || comp.type === 'NOR') {
        p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(5, h * 0.25, 5, h * 0.75, 0, h - py);
        (p as any).bezierVertex(w * 0.5, h - py, bodyW, h/2 + (effectiveH/4), bodyW, h/2);
        (p as any).bezierVertex(bodyW, h/2 - (effectiveH/4), w * 0.5, py, 0, py); p.endShape(p.CLOSE);
    } else if (comp.type === 'XOR') {
       p.noFill(); p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(5, h * 0.25, 5, h * 0.75, 0, h - py); p.endShape();
       p.fill(COLOR_COMPONENT_BG); p.beginShape(); p.vertex(4, py); (p as any).bezierVertex(9, h * 0.25, 9, h * 0.75, 4, h - py);
       (p as any).bezierVertex((w * 0.5) + 4, h - py, bodyW, h/2 + (effectiveH/4), bodyW, h/2);
       (p as any).bezierVertex(bodyW, h/2 - (effectiveH/4), (w * 0.5) + 4, py, 4, py); p.endShape(p.CLOSE);
    }
    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE);
        p.circle(w - bubbleR - 1, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke();
        p.fill('#1e293b');
        p.textSize(12);
        p.textStyle(p.BOLD);

        if (comp.type === ComponentType.INPUT_SWITCH || comp.type === ComponentType.CLOCK) {
           const side = comp.icPortSide || 'right';
           if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else if (comp.type === ComponentType.OUTPUT_LED) {
           const side = comp.icPortSide || 'left';
           if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else {
           p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        }
        p.textAlign(p.CENTER, p.CENTER);
        p.textStyle(p.NORMAL);
      }
  }

  private static drawArrow(p: p5Types, x: number, y: number, side: PortSide, size: number) {
    p.push();
    p.translate(x, y);
    if (side === 'right') p.rotate(0);
    else if (side === 'bottom') p.rotate(p.HALF_PI);
    else if (side === 'left') p.rotate(p.PI);
    else if (side === 'top') p.rotate(-p.HALF_PI);

    p.triangle(-size, -size/2, 0, 0, -size, size/2);
    p.pop();
  }
}

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

/**
 * Logic Rendering Engine & Geometric Utilities
 * Handles all P5.js drawing commands and hitbox calculations.
 */
export class CircuitRenderer {

  // --- Geometric Helpers (Used for Drawing & Hit Testing) ---

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    const componentSide = c.icPortSide || (isInput ? 'right' : 'left');
    switch (componentSide) {
        case 'top': return 'bottom';
        case 'bottom': return 'top';
        case 'left': return 'right';
        case 'right': return 'left';
    }
    return 'left';
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const getSide = CircuitRenderer.getSide; // Alias for brevity

          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          // Count pins on each side to determine needed size
          const topCount = inputs.filter(c => getSide(c, true) === 'top').length + outputs.filter(c => getSide(c, false) === 'top').length;
          const bottomCount = inputs.filter(c => getSide(c, true) === 'bottom').length + outputs.filter(c => getSide(c, false) === 'bottom').length;
          const leftCount = inputs.filter(c => getSide(c, true) === 'left').length + outputs.filter(c => getSide(c, false) === 'left').length;
          const rightCount = inputs.filter(c => getSide(c, true) === 'right').length + outputs.filter(c => getSide(c, false) === 'right').length;

          const width = Math.max(2, Math.max(topCount, bottomCount) + 1);
          const height = Math.max(2, Math.max(leftCount, rightCount) + 1);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 2, h: 2, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    // 1. Dynamic pin positioning for IO components
    if ((comp.type === ComponentType.INPUT_SWITCH || comp.type === ComponentType.CLOCK) && type === 'output') {
        const side = comp.icPortSide || 'right';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    // 2. Custom IC Pin Logic
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
             const getSide = CircuitRenderer.getSide;

             // Helper to sort pins consistently
             const sortGroup = (list: CircuitComponent[], isInput: boolean) => {
                return list.sort((a, b) => {
                    const sideA = getSide(a, isInput);
                    const sideB = getSide(b, isInput);
                    if (sideOrder[sideA] !== sideOrder[sideB]) return sideOrder[sideA] - sideOrder[sideB];
                    if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                });
             };

             const targetGroup = type === 'input' 
                ? sortGroup(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true)
                : sortGroup(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

             const targetComp = targetGroup[index];
             if (targetComp) {
                 const side = getSide(targetComp, type === 'input');
                 const sideGroup = targetGroup.filter(c => getSide(c, type === 'input') === side);
                 const localIndex = sideGroup.indexOf(targetComp);
                 const count = sideGroup.length;

                 // Distribute pins evenly along the edge
                 if (side === 'top') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y, side: 'top' };
                 } else if (side === 'bottom') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y + h, side: 'bottom' };
                 } else if (side === 'left') {
                     const step = h / (count + 1);
                     return { x: comp.x, y: comp.y + ((localIndex + 1) * step), side: 'left' };
                 } else { // right
                     const step = h / (count + 1);
                     return { x: comp.x + w, y: comp.y + ((localIndex + 1) * step), side: 'right' };
                 }
             }
         }
    }

    // 3. Standard Gates (Distribute evenly on Left/Right)
    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Drawing Methods ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
        p.strokeWeight(wire.state ? 3 : 2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output' }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);

        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);

        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') {
             cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        } else {
             cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };
        }

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    const py = 6;
    const padX = 4;
    const effectiveH = h - (py * 2);

    p.push();
    p.translate(comp.x, comp.y);

    // Body Style
    p.fill(COLOR_COMPONENT_BG);
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);

    // Dispatcher for Specific Component Rendering
    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h, padX, py, effectiveH);
    } else if (comp.type === ComponentType.CLOCK) {
        CircuitRenderer.drawClock(p, comp, w, h, padX, py, effectiveH);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h, padX);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, effectiveH, padX, py);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h, py, effectiveH);
    }

    // Custom Label Rendering
    CircuitRenderer.drawLabels(p, comp, w, h);

    // Standard Ports (Points)
    if (comp.type !== ComponentType.CUSTOM_IC && comp.type !== ComponentType.INPUT_SWITCH && comp.type !== ComponentType.OUTPUT_LED && comp.type !== ComponentType.CLOCK) {
        p.noStroke();
        p.fill('#64748b');
        for (let i = 0; i < inputs; i++) {
           const y = ((i + 1) * (h / (inputs + 1)));
           p.circle(0, y, 4);
        }
        for (let i = 0; i < outputs; i++) {
           const y = ((i + 1) * (h / (outputs + 1)));
           p.circle(w, y, 4);
        }
    }

    // Selection Highlight
    if (isSelected) {
        p.noFill();
        p.stroke('#3b82f6');
        p.strokeWeight(2);
        p.rect(-padX, -padX, w + (padX*2), h + (padX*2), 4);
    }

    p.pop();
  }

  // --- Sub-Renderers ---

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.rect(0, 0, w, h, 4);
    p.fill('#1e293b');
    p.noStroke();
    p.textSize(12);
    p.textStyle(p.BOLD);
    p.textAlign(p.CENTER, p.CENTER);
    p.text(comp.customLabel || "IC", w/2, h/2);

    // Draw small pins visual
    const funcDef = library.find(f => f.id === comp.functionId);
    if (funcDef) {
        p.textSize(8);
        p.textStyle(p.NORMAL);
        const drawPin = (c: CircuitComponent, isInput: boolean) => {
            const side = CircuitRenderer.getSide(c, isInput);
            const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
            const sorter = (a: CircuitComponent, b: CircuitComponent) => {
                 if (sideOrder[CircuitRenderer.getSide(a, isInput)] !== sideOrder[CircuitRenderer.getSide(b, isInput)]) return 0;
                 const sa = CircuitRenderer.getSide(a, isInput);
                 if (sa === 'top' || sa === 'bottom') return a.x - b.x;
                 return a.y - b.y;
            };

            const group = isInput 
               ? funcDef.components.filter(x => x.type === ComponentType.INPUT_SWITCH).sort(sorter)
               : funcDef.components.filter(x => x.type === ComponentType.OUTPUT_LED).sort(sorter);

            const sideGroup = group.filter(x => CircuitRenderer.getSide(x, isInput) === side);
            const localIndex = sideGroup.indexOf(c);
            const count = sideGroup.length;

            let px = 0, py = 0;
            p.fill('#64748b');
            if (side === 'top') {
                px = (localIndex + 1) * (w / (count + 1));
                py = 0;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.TOP);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, 6);
            } else if (side === 'bottom') {
                px = (localIndex + 1) * (w / (count + 1));
                py = h;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.BOTTOM);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, h - 6);
            } else if (side === 'left') {
                px = 0;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.LEFT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), 6, py);
            } else {
                px = w;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.RIGHT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), w - 6, py);
            }
        };
        funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH).forEach(c => drawPin(c, true));
        funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED).forEach(c => drawPin(c, false));
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number, py: number, effectiveH: number) {
    const isOn = comp.outputValues[0];
    const side = comp.icPortSide || 'right';

    // Box Visuals
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;

    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4); 

    p.noStroke();
    p.fill(isOn ? '#fff' : '#475569');
    p.textSize(10);
    p.textStyle(p.BOLD);
    p.textAlign(p.CENTER, p.CENTER);
    p.text(isOn ? "1" : "0", w/2, h/2);
    p.textStyle(p.NORMAL);
  }

  private static drawClock(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number, py: number, effectiveH: number) {
    const side = comp.icPortSide || 'right';
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;
    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    const isOn = comp.outputValues[0];
    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.fill(COLOR_COMPONENT_BG);
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

    p.noFill();
    p.stroke(isOn ? COLOR_WIRE_ON : '#64748b');
    p.strokeWeight(2);
    const cx = w/2;
    const cy = h/2;
    p.beginShape();
    p.vertex(cx - 6, cy + 3);
    p.vertex(cx - 3, cy + 3);
    p.vertex(cx - 3, cy - 3);
    p.vertex(cx + 3, cy - 3);
    p.vertex(cx + 3, cy + 3);
    p.vertex(cx + 6, cy + 3);
    p.endShape();
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number) {
    const isOn = comp.inputValues[0];
    const side = comp.icPortSide || 'left';
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;
    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    if (isOn) {
        p.noStroke();
        p.fill(245, 158, 11, 80); 
        p.rect(boxOffset - 3, boxOffset - 3, boxSize + 6, boxSize + 6, 6);
    }

    p.stroke(isOn ? COLOR_WIRE_ON : '#334155');
    p.fill(isOn ? COLOR_WIRE_ON : '#1e293b');
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, effectiveH: number, padX: number, py: number) {
    const h = effectiveH + (py * 2); 
    const yStep = h / 5;
    for(let i=0; i<4; i++) p.line(0, (i+1) * yStep, padX, (i+1) * yStep);
    p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, py, w - (padX*2), effectiveH, 4);
    p.noStroke(); p.fill('#ef4444'); p.textSize(16);
    let val = 0;
    if(comp.inputValues[0]) val += 1; if(comp.inputValues[1]) val += 2;
    if(comp.inputValues[2]) val += 4; if(comp.inputValues[3]) val += 8;
    p.text(val.toString(16).toUpperCase(), w/2, h/2 + 1);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number, py: number, effectiveH: number) {
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = w;
    if (isNegated) bodyW = w - (bubbleR*2) - 2;

    // Special case for NOT gate (Triangle)
    if (comp.type === 'NOT') {
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
        if (isNegated) {
             p.fill(COLOR_COMPONENT_BG);
             p.circle(w - bubbleR - 1, h / 2, bubbleR*2);
        }
        return;
    }

    const isXor = comp.type === 'XOR';
    const isOrFamily = ['OR', 'NOR', 'XOR'].includes(comp.type);

    let startX = 0;

    // Draw XOR extra input line
    if (isXor) {
        startX = 5;
        p.noFill();
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);
        p.beginShape();
        p.vertex(0, py);
        (p as any).bezierVertex(3, h * 0.33, 3, h * 0.66, 0, h - py);
        p.endShape();
    }

    p.fill(COLOR_COMPONENT_BG);
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);

    p.beginShape();

    if (isOrFamily) {
        // OR/NOR/XOR: Concave Back + Rounded Front (AND-style front)
        p.vertex(startX, py); // Top-Left
        p.vertex(bodyW * 0.5, py); // Top-Right (before curve)

        // Front Curve (Same as AND)
        (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);

        p.vertex(startX, h - py); // Bottom-Left

        // Back Curve (Concave)
        // Curves inward to x = startX + 5
        (p as any).bezierVertex(startX + 5, h * 0.75, startX + 5, h * 0.25, startX, py);

    } else {
        // AND/NAND: Flat Back + Rounded Front
        p.vertex(0, py);
        p.vertex(bodyW * 0.5, py);
        (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
        p.vertex(0, h - py);
        p.vertex(0, py); // Close box
    }

    p.endShape(p.CLOSE);

    // Draw Negation Bubble
    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); 
        p.stroke(COLOR_COMPONENT_STROKE);
        p.circle(w - bubbleR - 1, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke();
        p.fill('#1e293b');
        p.textSize(12);
        p.textStyle(p.BOLD);

        if (comp.type === ComponentType.INPUT_SWITCH || comp.type === ComponentType.CLOCK) {
           const side = comp.icPortSide || 'right';
           if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else if (comp.type === ComponentType.OUTPUT_LED) {
           const side = comp.icPortSide || 'left';
           if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else {
           p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        }
        p.textAlign(p.CENTER, p.CENTER);
        p.textStyle(p.NORMAL);
      }
  }

  private static drawArrow(p: p5Types, x: number, y: number, side: PortSide, size: number) {
    p.push();
    p.translate(x, y);
    if (side === 'right') p.rotate(0);
    else if (side === 'bottom') p.rotate(p.HALF_PI);
    else if (side === 'left') p.rotate(p.PI);
    else if (side === 'top') p.rotate(-p.HALF_PI);

    p.triangle(-size, -size/2, 0, 0, -size, size/2);
    p.pop();
  }
}

// Logic component types
export enum ComponentType {
  INPUT_SWITCH = 'INPUT',
  OUTPUT_LED = 'OUTPUT',
  NOT = 'NOT',
  AND = 'AND',
  OR = 'OR',
  NAND = 'NAND',
  NOR = 'NOR',
  XOR = 'XOR',
  HEX_DISPLAY = 'HEX',
  CUSTOM_IC = 'IC' // New: Custom Integrated Circuit
}

export type PortSide = 'top' | 'bottom' | 'left' | 'right';

export interface Point {
  x: number;
  y: number;
}

// A connection point on a component
export interface Port {
  id: string; // "input-0", "output-0"
  type: 'input' | 'output';
  relativePos: Point;
  label?: string;
}

// The definition of how a component behaves and looks
export interface ComponentDef {
  type: ComponentType;
  label: string;
  width: number;
  height: number;
  inputs: number; // count
  outputs: number; // count
  description: string;
}

// Global simulation state
export interface CircuitState {
  components: CircuitComponent[];
  wires: Wire[];
  tick: number;
}

// An instance of a component on the canvas
export interface CircuitComponent {
  id: string;
  type: ComponentType;
  x: number;
  y: number;
  inputValues: boolean[];
  outputValues: boolean[];
  customLabel?: string; // User defined label for Inputs/Outputs

  // For Custom ICs
  functionId?: string; // Links to the function definition
  internalState?: {    // Independent memory for this instance
    components: CircuitComponent[];
    wires: Wire[];
  };

  // Configuration for when this component acts as a port in a Custom IC
  icPortSide?: PortSide; 
}

// A connection between two ports
export interface Wire {
  id: string;
  fromCompId: string;
  fromPortIndex: number;
  toCompId: string;
  toPortIndex: number;
  state: boolean; // High (true) or Low (false)
}

// Function Circuit Definition (The "Class" of the IC)
export interface FunctionCircuit {
  id: string;
  name: string;
  components: CircuitComponent[];
  wires: Wire[];
}

import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';

/**
 * Logic Engine - Standard Synchronous (Double Buffered)
 */

const evaluateLogic = (type: ComponentType, inputs: boolean[], currentOutputs: boolean[]): boolean[] => {
  switch (type) {
    case ComponentType.INPUT_SWITCH:
      return currentOutputs;
    case ComponentType.OUTPUT_LED:
    case ComponentType.HEX_DISPLAY:
      return [];
    case ComponentType.NOT:
      return [!inputs[0]];
    case ComponentType.AND:
      return [inputs[0] && inputs[1]];
    case ComponentType.OR:
      return [inputs[0] || inputs[1]];
    case ComponentType.NAND:
      return [!(inputs[0] && inputs[1])];
    case ComponentType.NOR:
      return [!(inputs[0] || inputs[1])];
    case ComponentType.XOR:
      return [(inputs[0] ? true : false) !== (inputs[1] ? true : false)];
    default:
      return currentOutputs;
  }
};

// Helper to determine port order: Top -> Right -> Bottom -> Left
const getSide = (c: CircuitComponent, isInput: boolean): PortSide => {
    // Determine the visual orientation of the component inside the circuit
    // Input Switches default to pointing Right. Output LEDs default to receiving from Left.
    const componentSide = c.icPortSide || (isInput ? 'right' : 'left');

    // The IC Pin acts as the interface to the outside world.
    // If an Input Switch points Right (Signal flows Right), the IC Input Pin must be on the Left edge.
    // If an Output LED receives from Left (Signal flows Right), the IC Output Pin must be on the Right edge.
    // Therefore, the IC Port Side is always opposite to the Component's Visual Side.
    switch (componentSide) {
        case 'top': return 'bottom';
        case 'bottom': return 'top';
        case 'left': return 'right';
        case 'right': return 'left';
    }
    return 'left';
};

const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

const sortComponents = (components: CircuitComponent[], isInput: boolean) => {
    return components.sort((a, b) => {
        const sideA = getSide(a, isInput);
        const sideB = getSide(b, isInput);
        if (sideOrder[sideA] !== sideOrder[sideB]) {
            return sideOrder[sideA] - sideOrder[sideB];
        }
        // Same side: Top/Bottom sort by X, Left/Right sort by Y
        if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
        return a.y - b.y;
    });
};

export const stepSimulation = (
  currentComponents: CircuitComponent[],
  wires: Wire[],
  functionLibrary: FunctionCircuit[] = []
): { components: CircuitComponent[], wires: Wire[] } => {

  // 1. Create the "Next" buffer (Swap Memory)
  const nextComponents = currentComponents.map(c => ({
    ...c,
    inputValues: [...c.inputValues],
    outputValues: [...c.outputValues],
    internalState: c.internalState ? {
        components: [...c.internalState.components],
        wires: [...c.internalState.wires]
    } : undefined
  }));

  // Create Maps
  const prevCompMap = new Map(currentComponents.map(c => [c.id, c]));
  const nextCompMap = new Map(nextComponents.map(c => [c.id, c]));

  // 2. Reset inputs
  for (const comp of nextComponents) {
    comp.inputValues.fill(false);
  }

  // 3. Propagate Signals (Main Circuit)
  for (const wire of wires) {
    const sourceComp = prevCompMap.get(wire.fromCompId);
    const destComp = nextCompMap.get(wire.toCompId);

    if (sourceComp && destComp) {
      if (sourceComp.outputValues[wire.fromPortIndex]) {
        destComp.inputValues[wire.toPortIndex] = true;
      }
    }
  }

  // 4. Compute Logic Gates
  for (const comp of nextComponents) {
    if (comp.type === ComponentType.INPUT_SWITCH) continue;

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId && comp.internalState) {
        // --- CUSTOM IC SIMULATION ---
        const funcDef = functionLibrary.find(f => f.id === comp.functionId);

        if (funcDef) {
            // A. Identify IO Mappings in Definition
            // Sort inputs/outputs to match the visual pin layout (Side order -> Coordinate)
            const inputsDef = sortComponents(
                funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH),
                true
            );
            const outputsDef = sortComponents(
                funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED),
                false
            );

            // B. Inject External Inputs -> Internal Switches
            const internalState = comp.internalState;

            inputsDef.forEach((def, index) => {
                if (index < comp.inputValues.length) {
                    const val = comp.inputValues[index];
                    // Find corresponding component in instance state
                    const internalSwitch = internalState.components.find(c => c.id === def.id);
                    if (internalSwitch) {
                        internalSwitch.outputValues = [val]; // Force switch state
                    }
                }
            });

            // C. Step Internal Simulation
            const result = stepSimulation(internalState.components, internalState.wires, functionLibrary);
            comp.internalState = result; // Update internal memory

            // D. Extract Internal LEDs -> External Outputs
            const newOutputs: boolean[] = [];
            outputsDef.forEach((def) => {
                const internalLed = result.components.find(c => c.id === def.id);
                if (internalLed && internalLed.inputValues.length > 0) {
                    newOutputs.push(internalLed.inputValues[0]);
                } else {
                    newOutputs.push(false);
                }
            });
            comp.outputValues = newOutputs;
        }
    } else {
        // Standard Primitive Logic
        comp.outputValues = evaluateLogic(comp.type, comp.inputValues, comp.outputValues);
    }
  }

  // 5. Update Wire Visuals
  const nextWires = wires.map(w => {
    const sourceComp = nextCompMap.get(w.fromCompId);
    return {
      ...w,
      state: sourceComp ? sourceComp.outputValues[w.fromPortIndex] : false
    };
  });

  return { components: nextComponents, wires: nextWires };
};

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

/**
 * Logic Rendering Engine & Geometric Utilities
 * Handles all P5.js drawing commands and hitbox calculations.
 */
export class CircuitRenderer {

  // --- Geometric Helpers (Used for Drawing & Hit Testing) ---

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    const componentSide = c.icPortSide || (isInput ? 'right' : 'left');
    switch (componentSide) {
        case 'top': return 'bottom';
        case 'bottom': return 'top';
        case 'left': return 'right';
        case 'right': return 'left';
    }
    return 'left';
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const getSide = CircuitRenderer.getSide; // Alias for brevity

          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          // Count pins on each side to determine needed size
          const topCount = inputs.filter(c => getSide(c, true) === 'top').length + outputs.filter(c => getSide(c, false) === 'top').length;
          const bottomCount = inputs.filter(c => getSide(c, true) === 'bottom').length + outputs.filter(c => getSide(c, false) === 'bottom').length;
          const leftCount = inputs.filter(c => getSide(c, true) === 'left').length + outputs.filter(c => getSide(c, false) === 'left').length;
          const rightCount = inputs.filter(c => getSide(c, true) === 'right').length + outputs.filter(c => getSide(c, false) === 'right').length;

          const width = Math.max(2, Math.max(topCount, bottomCount) + 1);
          const height = Math.max(2, Math.max(leftCount, rightCount) + 1);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 2, h: 2, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    // 1. Dynamic pin positioning for IO components
    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    // 2. Custom IC Pin Logic
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
             const getSide = CircuitRenderer.getSide;

             // Helper to sort pins consistently
             const sortGroup = (list: CircuitComponent[], isInput: boolean) => {
                return list.sort((a, b) => {
                    const sideA = getSide(a, isInput);
                    const sideB = getSide(b, isInput);
                    if (sideOrder[sideA] !== sideOrder[sideB]) return sideOrder[sideA] - sideOrder[sideB];
                    if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                });
             };

             const targetGroup = type === 'input' 
                ? sortGroup(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true)
                : sortGroup(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

             const targetComp = targetGroup[index];
             if (targetComp) {
                 const side = getSide(targetComp, type === 'input');
                 const sideGroup = targetGroup.filter(c => getSide(c, type === 'input') === side);
                 const localIndex = sideGroup.indexOf(targetComp);
                 const count = sideGroup.length;

                 // Distribute pins evenly along the edge
                 if (side === 'top') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y, side: 'top' };
                 } else if (side === 'bottom') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y + h, side: 'bottom' };
                 } else if (side === 'left') {
                     const step = h / (count + 1);
                     return { x: comp.x, y: comp.y + ((localIndex + 1) * step), side: 'left' };
                 } else { // right
                     const step = h / (count + 1);
                     return { x: comp.x + w, y: comp.y + ((localIndex + 1) * step), side: 'right' };
                 }
             }
         }
    }

    // 3. Standard Gates (Distribute evenly on Left/Right)
    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Drawing Methods ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
        p.strokeWeight(wire.state ? 3 : 2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output' }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);

        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);

        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') {
             cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        } else {
             cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };
        }

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    const py = 6;
    const padX = 4;
    const effectiveH = h - (py * 2);

    p.push();
    p.translate(comp.x, comp.y);

    // Body Style
    p.fill(COLOR_COMPONENT_BG);
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);

    // Dispatcher for Specific Component Rendering
    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h, padX, py, effectiveH);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h, padX);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, effectiveH, padX, py);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h, py, effectiveH);
    }

    // Custom Label Rendering
    CircuitRenderer.drawLabels(p, comp, w, h);

    // Standard Ports (Points)
    if (comp.type !== ComponentType.CUSTOM_IC && comp.type !== ComponentType.INPUT_SWITCH && comp.type !== ComponentType.OUTPUT_LED) {
        p.noStroke();
        p.fill('#64748b');
        for (let i = 0; i < inputs; i++) {
           const y = ((i + 1) * (h / (inputs + 1)));
           p.circle(0, y, 4);
        }
        for (let i = 0; i < outputs; i++) {
           const y = ((i + 1) * (h / (outputs + 1)));
           p.circle(w, y, 4);
        }
    }

    // Selection Highlight
    if (isSelected) {
        p.noFill();
        p.stroke('#3b82f6');
        p.strokeWeight(2);
        p.rect(-padX, -padX, w + (padX*2), h + (padX*2), 4);
    }

    p.pop();
  }

  // --- Sub-Renderers ---

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.rect(0, 0, w, h, 4);
    p.fill('#1e293b');
    p.noStroke();
    p.textSize(12);
    p.textStyle(p.BOLD);
    p.textAlign(p.CENTER, p.CENTER);
    p.text(comp.customLabel || "IC", w/2, h/2);

    // Draw small pins visual
    const funcDef = library.find(f => f.id === comp.functionId);
    if (funcDef) {
        p.textSize(8);
        p.textStyle(p.NORMAL);
        const drawPin = (c: CircuitComponent, isInput: boolean) => {
            const side = CircuitRenderer.getSide(c, isInput);
            const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
            const sorter = (a: CircuitComponent, b: CircuitComponent) => {
                 if (sideOrder[CircuitRenderer.getSide(a, isInput)] !== sideOrder[CircuitRenderer.getSide(b, isInput)]) return 0;
                 const sa = CircuitRenderer.getSide(a, isInput);
                 if (sa === 'top' || sa === 'bottom') return a.x - b.x;
                 return a.y - b.y;
            };

            const group = isInput 
               ? funcDef.components.filter(x => x.type === ComponentType.INPUT_SWITCH).sort(sorter)
               : funcDef.components.filter(x => x.type === ComponentType.OUTPUT_LED).sort(sorter);

            const sideGroup = group.filter(x => CircuitRenderer.getSide(x, isInput) === side);
            const localIndex = sideGroup.indexOf(c);
            const count = sideGroup.length;

            let px = 0, py = 0;
            p.fill('#64748b');
            if (side === 'top') {
                px = (localIndex + 1) * (w / (count + 1));
                py = 0;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.TOP);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, 6);
            } else if (side === 'bottom') {
                px = (localIndex + 1) * (w / (count + 1));
                py = h;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.BOTTOM);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, h - 6);
            } else if (side === 'left') {
                px = 0;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.LEFT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), 6, py);
            } else {
                px = w;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.RIGHT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), w - 6, py);
            }
        };
        funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH).forEach(c => drawPin(c, true));
        funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED).forEach(c => drawPin(c, false));
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number, py: number, effectiveH: number) {
    const isOn = comp.outputValues[0];
    const side = comp.icPortSide || 'right';

    // Box Visuals
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;

    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4); 

    p.noStroke();
    p.fill(isOn ? '#fff' : '#475569');
    p.textSize(10);
    p.textStyle(p.BOLD);
    p.textAlign(p.CENTER, p.CENTER);
    p.text(isOn ? "1" : "0", w/2, h/2);
    p.textStyle(p.NORMAL);
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number) {
    const isOn = comp.inputValues[0];
    const side = comp.icPortSide || 'left';
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;
    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    if (isOn) {
        p.noStroke();
        p.fill(245, 158, 11, 80); 
        p.rect(boxOffset - 3, boxOffset - 3, boxSize + 6, boxSize + 6, 6);
    }

    p.stroke(isOn ? COLOR_WIRE_ON : '#334155');
    p.fill(isOn ? COLOR_WIRE_ON : '#1e293b');
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, effectiveH: number, padX: number, py: number) {
    const h = effectiveH + (py * 2); 
    const yStep = h / 5;
    for(let i=0; i<4; i++) p.line(0, (i+1) * yStep, padX, (i+1) * yStep);
    p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, py, w - (padX*2), effectiveH, 4);
    p.noStroke(); p.fill('#ef4444'); p.textSize(16);
    let val = 0;
    if(comp.inputValues[0]) val += 1; if(comp.inputValues[1]) val += 2;
    if(comp.inputValues[2]) val += 4; if(comp.inputValues[3]) val += 8;
    p.text(val.toString(16).toUpperCase(), w/2, h/2 + 1);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number, py: number, effectiveH: number) {
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = w;
    if (isNegated) bodyW = w - (bubbleR*2) - 2;

    // Special case for NOT gate (Triangle)
    if (comp.type === 'NOT') {
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
        if (isNegated) {
             p.fill(COLOR_COMPONENT_BG);
             p.circle(w - bubbleR - 1, h / 2, bubbleR*2);
        }
        return;
    }

    const isXor = comp.type === 'XOR';
    const isOrFamily = ['OR', 'NOR', 'XOR'].includes(comp.type);

    let startX = 0;

    // Draw XOR extra input line
    if (isXor) {
        startX = 5;
        p.noFill();
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);
        p.beginShape();
        p.vertex(0, py);
        (p as any).bezierVertex(3, h * 0.33, 3, h * 0.66, 0, h - py);
        p.endShape();
    }

    p.fill(COLOR_COMPONENT_BG);
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);

    p.beginShape();

    if (isOrFamily) {
        // OR/NOR/XOR: Concave Back + Rounded Front (AND-style front)
        p.vertex(startX, py); // Top-Left
        p.vertex(bodyW * 0.5, py); // Top-Right (before curve)

        // Front Curve (Same as AND)
        (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);

        p.vertex(startX, h - py); // Bottom-Left

        // Back Curve (Concave)
        // Curves inward to x = startX + 5
        (p as any).bezierVertex(startX + 5, h * 0.75, startX + 5, h * 0.25, startX, py);

    } else {
        // AND/NAND: Flat Back + Rounded Front
        p.vertex(0, py);
        p.vertex(bodyW * 0.5, py);
        (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
        p.vertex(0, h - py);
        p.vertex(0, py); // Close box
    }

    p.endShape(p.CLOSE);

    // Draw Negation Bubble
    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); 
        p.stroke(COLOR_COMPONENT_STROKE);
        p.circle(w - bubbleR - 1, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke();
        p.fill('#1e293b');
        p.textSize(12);
        p.textStyle(p.BOLD);

        if (comp.type === ComponentType.INPUT_SWITCH) {
           const side = comp.icPortSide || 'right';
           if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else if (comp.type === ComponentType.OUTPUT_LED) {
           const side = comp.icPortSide || 'left';
           if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else {
           p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        }
        p.textAlign(p.CENTER, p.CENTER);
        p.textStyle(p.NORMAL);
      }
  }

  private static drawArrow(p: p5Types, x: number, y: number, side: PortSide, size: number) {
    p.push();
    p.translate(x, y);
    if (side === 'right') p.rotate(0);
    else if (side === 'bottom') p.rotate(p.HALF_PI);
    else if (side === 'left') p.rotate(p.PI);
    else if (side === 'top') p.rotate(-p.HALF_PI);

    p.triangle(-size, -size/2, 0, 0, -size, size/2);
    p.pop();
  }
}

import React from 'react';
import { ComponentType, FunctionCircuit } from '../types';
import { COMPONENT_DEFINITIONS } from '../constants';

interface SidebarProps {
  selectedTool: 'SELECT' | 'DELETE';
  onSelectTool: (t: 'SELECT' | 'DELETE') => void;
  onTouchStartItem?: (type: ComponentType, e: React.TouchEvent, functionId?: string) => void;
  functionLibrary: FunctionCircuit[];
}

const Sidebar: React.FC<SidebarProps> = ({ selectedTool, onSelectTool, onTouchStartItem, functionLibrary }) => {
  const groups = [
    { name: 'I/O', items: [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.HEX_DISPLAY] },
    { name: 'Gates', items: [ComponentType.NOT, ComponentType.AND, ComponentType.OR, ComponentType.NAND, ComponentType.NOR, ComponentType.XOR] }
  ];

  const handleDragStart = (e: React.DragEvent, type: ComponentType, functionId?: string) => {
    e.dataTransfer.setData('application/react-logic-sim', JSON.stringify({ type, functionId }));
    e.dataTransfer.effectAllowed = 'copy';
  };

  // Filter out Main Circuit from draggable list (it can't contain itself recursively easily)
  const draggableFunctions = functionLibrary.filter(f => f.id !== 'main');

  return (
    <div className="w-64 bg-white border-r border-slate-200 flex flex-col h-full shadow-lg z-10">
      <div className="p-4 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 tracking-tight">LogicFlow</h1>
        <p className="text-xs text-slate-400 mt-1">Simulator v1.3</p>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">

        {/* Tools */}
        <div>
          <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">Tools</h3>
          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={() => onSelectTool('SELECT')}
              className={`p-2 rounded text-sm font-medium transition-colors ${selectedTool === 'SELECT' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              Cursor
            </button>
            <button
              onClick={() => onSelectTool('DELETE')}
              className={`p-2 rounded text-sm font-medium transition-colors ${selectedTool === 'DELETE' ? 'bg-red-500 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              Delete
            </button>
          </div>
        </div>

        {/* Components */}
        {groups.map(group => (
          <div key={group.name}>
            <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">{group.name}</h3>
            <div className="grid grid-cols-2 gap-3">
              {group.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                return (
                  <div
                    key={type}
                    draggable={true}
                    onDragStart={(e) => handleDragStart(e, type)}
                    onTouchStart={(e) => onTouchStartItem && onTouchStartItem(type, e)}
                    className="flex flex-col items-center justify-center p-3 rounded border-2 border-slate-100 bg-white hover:border-slate-300 hover:shadow-sm transition-all duration-200 cursor-grab active:cursor-grabbing touch-none"
                  >
                    <div className="w-8 h-8 mb-2 border border-slate-300 rounded flex items-center justify-center bg-white text-[10px] font-bold text-slate-600 pointer-events-none">
                      {def.label.substring(0,3)}
                    </div>
                    <span className="text-xs font-medium text-slate-700 pointer-events-none">{def.label}</span>
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {/* Custom Functions */}
        {draggableFunctions.length > 0 && (
            <div>
                 <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">My Functions</h3>
                 <div className="grid grid-cols-1 gap-2">
                    {draggableFunctions.map(func => (
                        <div
                            key={func.id}
                            draggable={true}
                            onDragStart={(e) => handleDragStart(e, ComponentType.CUSTOM_IC, func.id)}
                            onTouchStart={(e) => onTouchStartItem && onTouchStartItem(ComponentType.CUSTOM_IC, e, func.id)}
                            className="flex items-center p-2 rounded border border-slate-200 bg-blue-50 hover:border-blue-300 hover:shadow-sm transition-all duration-200 cursor-grab active:cursor-grabbing touch-none"
                        >
                             <div className="w-6 h-6 mr-3 border border-blue-200 rounded flex items-center justify-center bg-white text-[9px] font-bold text-blue-600 pointer-events-none">
                                IC
                             </div>
                             <span className="text-sm font-medium text-slate-700 pointer-events-none truncate">{func.name}</span>
                        </div>
                    ))}
                 </div>
            </div>
        )}

      </div>
    </div>
  );
};

