import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import { ComponentType, CircuitComponent, FunctionCircuit } from './types';
import { COMPONENT_DEFINITIONS } from './constants';
import { useProjectManager } from './hooks/useProjectManager';

const App: React.FC = () => {
  // -- UI State --
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false);

  // Speed Control State
  // Slider 0-100. 0 = 500ms (Slow), 100 = 0ms (Max/Unlimited)
  const [speedSlider, setSpeedSlider] = useState(90); 
  // Calculate ms from slider: 0 -> 500, 100 -> 0. Linear mapping.
  const tickSpeed = speedSlider === 100 ? 0 : Math.max(1, 500 - (speedSlider * 5));

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);

  // -- Component Selection State --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  // -- Drag State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string} | null>(null);

  // -- References --
  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // -- Project Data Management --
  const {
      functions,
      activeFunctionId,
      activeFunction,
      lastSaved,
      dataVersion,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  } = useProjectManager(canvasRef);

  // -- Interactions --

  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent, functionId?: string) => {
    const touch = e.touches[0];
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left && dragPos.x <= rect.right &&
          dragPos.y >= rect.top && dragPos.y <= rect.bottom
        ) {
          setPendingDrop({ type: draggedType, x: dragPos.x - rect.left, y: dragPos.y - rect.top, functionId: draggedFuncId });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos, draggedFuncId]);

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            if (Array.isArray(parsed)) {
                if (confirm("Replace current project?")) {
                    importData(parsed, true);
                    setSelectedComponent(null);
                    setIsPlaying(false);
                }
            } else if (parsed.id) {
                importData(parsed, false);
                alert(`Imported: ${parsed.name}`);
            }
        } catch (err) { alert("Invalid File"); }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const handleExport = (type: 'PROJECT' | 'FUNCTION') => {
      const data = type === 'PROJECT' 
        ? functions.map(f => f.id === activeFunctionId && canvasRef.current ? {...f, ...canvasRef.current.getData()} : f)
        : (canvasRef.current ? {...activeFunction, ...canvasRef.current.getData()} : activeFunction);

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = type === 'PROJECT' ? `project.json` : `${activeFunction.name.replace(/\s+/g, '_')}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setIsProjectMenuOpen(false);
  };

  const createFunction = (e: React.FormEvent) => {
      e.preventDefault();
      if (newFuncName.trim()) {
          addFunction(newFuncName);
          setNewFuncName("");
          setIsModalOpen(false);
      }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) setTempLabel(comp.customLabel || "");
      else setTempLabel("");
  };

  const updateProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">
        {/* HUD */}
        <div className="absolute top-4 left-4 right-4 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap items-center justify-between px-4 py-2 z-10 border border-slate-200 gap-2">

          <div className="flex items-center space-x-2">
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => { setIsPlaying(false); switchToFunction(e.target.value); }}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
               </select>
               <button onClick={() => setIsModalOpen(true)} className="ml-2 w-8 h-8 bg-blue-100 text-blue-600 rounded hover:bg-blue-200 font-bold">+</button>
               {activeFunctionId !== 'main' && (
                 <button onClick={() => deleteFunction(activeFunctionId)} className="ml-1 w-8 h-8 bg-red-100 text-red-500 rounded hover:bg-red-200 font-bold">×</button>
               )}
             </div>

             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded text-sm font-semibold text-slate-700 w-24"
             >
               {isPlaying ? 'Pause' : 'Resume'}
             </button>

             <div className="relative">
                <button onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)} className="px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700">
                    Project ▼
                </button>
                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                        <div className="px-4 py-2 text-xs text-slate-400 border-b mb-1">
                            {lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Unsaved'}
                        </div>
                        <button onClick={() => { persist(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">💾 Save Now</button>
                        <button onClick={() => { fileInputRef.current?.click(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📂 Import...</button>
                        <button onClick={() => handleExport('PROJECT')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📦 Export All</button>
                        <button onClick={() => handleExport('FUNCTION')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📄 Export Active</button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={() => { if(confirm("Clear all data?")) clearData(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50">🗑️ Reset</button>
                    </div>
                )}
                {isProjectMenuOpen && <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>}
             </div>
          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end">
             {selectedComponent && (
                 <div className="flex items-center space-x-2 flex-1 md:flex-none justify-center">
                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <input 
                            type="text" 
                            value={tempLabel}
                            onChange={(e) => { setTempLabel(e.target.value); updateProp({ customLabel: e.target.value }); }}
                            className="bg-white border border-yellow-200 text-sm px-2 py-1 rounded w-24 focus:outline-none"
                            placeholder="Label"
                        />
                     </div>
                     {['INPUT','OUTPUT'].includes(selectedComponent.type) && (
                         <select 
                             value={selectedComponent.icPortSide || (selectedComponent.type === 'OUTPUT' ? 'left' : 'right')}
                             onChange={(e) => updateProp({ icPortSide: e.target.value as any })}
                             className="bg-white border border-blue-200 text-sm px-2 py-1 rounded focus:outline-none"
                         >
                             <option value="top">Top</option>
                             <option value="bottom">Bottom</option>
                             <option value="left">Left</option>
                             <option value="right">Right</option>
                         </select>
                     )}
                 </div>
             )}

             {/* Speed Control */}
             <div className="flex items-center space-x-2 bg-slate-100 rounded p-1 border border-slate-200 px-3" title="Simulation Speed">
                <span className="text-xs font-bold text-slate-500 w-12 text-right">
                  {tickSpeed === 0 ? "MAX" : `${tickSpeed}ms`}
                </span>
                <input 
                    type="range" 
                    min="0" 
                    max="100" 
                    value={speedSlider} 
                    onChange={(e) => setSpeedSlider(Number(e.target.value))} 
                    className="w-24 accent-slate-600 cursor-pointer" 
                />
             </div>
          </div>
        </div>

        {/* Canvas */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={() => setPendingDrop(null)}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Drag Ghost */}
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-80" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">{draggedType === 'IC' ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}</span>
            </div>
          </div>
        )}

        {/* Modal */}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100"><h3 className="font-bold">New Function</h3></div>
              <form onSubmit={createFunction} className="p-4">
                <input autoFocus type="text" value={newFuncName} onChange={(e) => setNewFuncName(e.target.value)} placeholder="Function Name" className="w-full px-3 py-2 border rounded-lg mb-4" />
                <div className="flex justify-end space-x-2">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-bold text-slate-500">Cancel</button>
                  <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg">Create</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

