import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

/**
 * Logic Rendering Engine & Geometric Utilities
 * Handles all P5.js drawing commands and hitbox calculations.
 */
export class CircuitRenderer {

  // --- Geometric Helpers (Used for Drawing & Hit Testing) ---

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    const componentSide = c.icPortSide || (isInput ? 'right' : 'left');
    switch (componentSide) {
        case 'top': return 'bottom';
        case 'bottom': return 'top';
        case 'left': return 'right';
        case 'right': return 'left';
    }
    return 'left';
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const getSide = CircuitRenderer.getSide; // Alias for brevity

          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          // Count pins on each side to determine needed size
          const topCount = inputs.filter(c => getSide(c, true) === 'top').length + outputs.filter(c => getSide(c, false) === 'top').length;
          const bottomCount = inputs.filter(c => getSide(c, true) === 'bottom').length + outputs.filter(c => getSide(c, false) === 'bottom').length;
          const leftCount = inputs.filter(c => getSide(c, true) === 'left').length + outputs.filter(c => getSide(c, false) === 'left').length;
          const rightCount = inputs.filter(c => getSide(c, true) === 'right').length + outputs.filter(c => getSide(c, false) === 'right').length;

          const width = Math.max(2, Math.max(topCount, bottomCount) + 1);
          const height = Math.max(2, Math.max(leftCount, rightCount) + 1);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 2, h: 2, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    // 1. Dynamic pin positioning for IO components
    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    // 2. Custom IC Pin Logic
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
             const getSide = CircuitRenderer.getSide;

             // Helper to sort pins consistently
             const sortGroup = (list: CircuitComponent[], isInput: boolean) => {
                return list.sort((a, b) => {
                    const sideA = getSide(a, isInput);
                    const sideB = getSide(b, isInput);
                    if (sideOrder[sideA] !== sideOrder[sideB]) return sideOrder[sideA] - sideOrder[sideB];
                    if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                });
             };

             const targetGroup = type === 'input' 
                ? sortGroup(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true)
                : sortGroup(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

             const targetComp = targetGroup[index];
             if (targetComp) {
                 const side = getSide(targetComp, type === 'input');
                 const sideGroup = targetGroup.filter(c => getSide(c, type === 'input') === side);
                 const localIndex = sideGroup.indexOf(targetComp);
                 const count = sideGroup.length;

                 // Distribute pins evenly along the edge
                 if (side === 'top') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y, side: 'top' };
                 } else if (side === 'bottom') {
                     const step = w / (count + 1);
                     return { x: comp.x + ((localIndex + 1) * step), y: comp.y + h, side: 'bottom' };
                 } else if (side === 'left') {
                     const step = h / (count + 1);
                     return { x: comp.x, y: comp.y + ((localIndex + 1) * step), side: 'left' };
                 } else { // right
                     const step = h / (count + 1);
                     return { x: comp.x + w, y: comp.y + ((localIndex + 1) * step), side: 'right' };
                 }
             }
         }
    }

    // 3. Standard Gates (Distribute evenly on Left/Right)
    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Drawing Methods ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
        p.strokeWeight(wire.state ? 3 : 2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output' }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);

        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(2);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);

        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') {
             cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        } else {
             cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };
        }

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    const py = 6;
    const padX = 4;
    const effectiveH = h - (py * 2);

    p.push();
    p.translate(comp.x, comp.y);

    // Body Style
    p.fill(COLOR_COMPONENT_BG);
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);

    // Dispatcher for Specific Component Rendering
    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h, padX, py, effectiveH);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h, padX);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, effectiveH, padX, py);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h, py, effectiveH);
    }

    // Custom Label Rendering
    CircuitRenderer.drawLabels(p, comp, w, h);

    // Standard Ports (Points)
    if (comp.type !== ComponentType.CUSTOM_IC && comp.type !== ComponentType.INPUT_SWITCH && comp.type !== ComponentType.OUTPUT_LED) {
        p.noStroke();
        p.fill('#64748b');
        for (let i = 0; i < inputs; i++) {
           const y = ((i + 1) * (h / (inputs + 1)));
           p.circle(0, y, 4);
        }
        for (let i = 0; i < outputs; i++) {
           const y = ((i + 1) * (h / (outputs + 1)));
           p.circle(w, y, 4);
        }
    }

    // Selection Highlight
    if (isSelected) {
        p.noFill();
        p.stroke('#3b82f6');
        p.strokeWeight(2);
        p.rect(-padX, -padX, w + (padX*2), h + (padX*2), 4);
    }

    p.pop();
  }

  // --- Sub-Renderers ---

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.rect(0, 0, w, h, 4);
    p.fill('#1e293b');
    p.noStroke();
    p.textSize(12);
    p.textStyle(p.BOLD);
    p.textAlign(p.CENTER, p.CENTER);
    p.text(comp.customLabel || "IC", w/2, h/2);

    // Draw small pins visual
    const funcDef = library.find(f => f.id === comp.functionId);
    if (funcDef) {
        p.textSize(8);
        p.textStyle(p.NORMAL);
        const drawPin = (c: CircuitComponent, isInput: boolean) => {
            const side = CircuitRenderer.getSide(c, isInput);
            const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
            const sorter = (a: CircuitComponent, b: CircuitComponent) => {
                 if (sideOrder[CircuitRenderer.getSide(a, isInput)] !== sideOrder[CircuitRenderer.getSide(b, isInput)]) return 0;
                 const sa = CircuitRenderer.getSide(a, isInput);
                 if (sa === 'top' || sa === 'bottom') return a.x - b.x;
                 return a.y - b.y;
            };

            const group = isInput 
               ? funcDef.components.filter(x => x.type === ComponentType.INPUT_SWITCH).sort(sorter)
               : funcDef.components.filter(x => x.type === ComponentType.OUTPUT_LED).sort(sorter);

            const sideGroup = group.filter(x => CircuitRenderer.getSide(x, isInput) === side);
            const localIndex = sideGroup.indexOf(c);
            const count = sideGroup.length;

            let px = 0, py = 0;
            p.fill('#64748b');
            if (side === 'top') {
                px = (localIndex + 1) * (w / (count + 1));
                py = 0;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.TOP);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, 6);
            } else if (side === 'bottom') {
                px = (localIndex + 1) * (w / (count + 1));
                py = h;
                p.circle(px, py, 4);
                p.textAlign(p.CENTER, p.BOTTOM);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, h - 6);
            } else if (side === 'left') {
                px = 0;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.LEFT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), 6, py);
            } else {
                px = w;
                py = (localIndex + 1) * (h / (count + 1));
                p.circle(px, py, 4);
                p.textAlign(p.RIGHT, p.CENTER);
                p.text(c.customLabel || (isInput ? "IN" : "OUT"), w - 6, py);
            }
        };
        funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH).forEach(c => drawPin(c, true));
        funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED).forEach(c => drawPin(c, false));
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number, py: number, effectiveH: number) {
    const isOn = comp.outputValues[0];
    const side = comp.icPortSide || 'right';

    // Box Visuals
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;

    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
    p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4); 

    p.noStroke();
    p.fill(isOn ? '#fff' : '#475569');
    p.textSize(10);
    p.textStyle(p.BOLD);
    p.textAlign(p.CENTER, p.CENTER);
    p.text(isOn ? "1" : "0", w/2, h/2);
    p.textStyle(p.NORMAL);
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number, padX: number) {
    const isOn = comp.inputValues[0];
    const side = comp.icPortSide || 'left';
    const boxSize = GRID_SIZE * 0.6;
    const boxOffset = (GRID_SIZE - boxSize) / 2;

    let portX = 0, portY = 0;
    if (side === 'right') { portX = w; portY = h/2; }
    else if (side === 'left') { portX = 0; portY = h/2; }
    else if (side === 'top') { portX = w/2; portY = 0; }
    else if (side === 'bottom') { portX = w/2; portY = h; }

    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(w/2, h/2, portX, portY);

    p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

    if (isOn) {
        p.noStroke();
        p.fill(245, 158, 11, 80); 
        p.rect(boxOffset - 3, boxOffset - 3, boxSize + 6, boxSize + 6, 6);
    }

    p.stroke(isOn ? COLOR_WIRE_ON : '#334155');
    p.fill(isOn ? COLOR_WIRE_ON : '#1e293b');
    p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, effectiveH: number, padX: number, py: number) {
    const h = effectiveH + (py * 2); 
    const yStep = h / 5;
    for(let i=0; i<4; i++) p.line(0, (i+1) * yStep, padX, (i+1) * yStep);
    p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, py, w - (padX*2), effectiveH, 4);
    p.noStroke(); p.fill('#ef4444'); p.textSize(16);
    let val = 0;
    if(comp.inputValues[0]) val += 1; if(comp.inputValues[1]) val += 2;
    if(comp.inputValues[2]) val += 4; if(comp.inputValues[3]) val += 8;
    p.text(val.toString(16).toUpperCase(), w/2, h/2 + 1);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number, py: number, effectiveH: number) {
    // ゲートの見た目の幅を少し縮める (Shrink width for styling)
    const shrink = 10;
    const gateW = w - shrink;

    // 出力ピンへの接続線を描画
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);
    p.line(gateW, h/2, w, h/2);

    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;

    // ゲート本体の幅（否定バブルがある場合はその分さらに引く）
    let bodyW = gateW;
    if (isNegated) bodyW = gateW - (bubbleR*2); // バブルの直径分空ける

    // Special case for NOT gate (Triangle)
    if (comp.type === 'NOT') {
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
        if (isNegated) {
             p.fill(COLOR_COMPONENT_BG);
             p.circle(gateW - bubbleR, h / 2, bubbleR*2); // バブル位置調整
        }
        return;
    }

    const isXor = comp.type === 'XOR';
    const isOrFamily = ['OR', 'NOR', 'XOR'].includes(comp.type);

    let startX = 0;

    // Draw XOR extra input line
    if (isXor) {
        startX = 5;
        p.noFill();
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);
        p.beginShape();
        p.vertex(0, py);
        (p as any).bezierVertex(3, h * 0.33, 3, h * 0.66, 0, h - py);
        p.endShape();
    }

    p.fill(COLOR_COMPONENT_BG);
    p.stroke(COLOR_COMPONENT_STROKE);
    p.strokeWeight(2);

    p.beginShape();

    if (isOrFamily) {
        // OR/NOR/XOR: Concave Back + Rounded Front (AND-style front)
        p.vertex(startX, py); // Top-Left
        p.vertex(bodyW * 0.5, py); // Top-Right (before curve)

        // Front Curve (Same as AND)
        (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);

        p.vertex(startX, h - py); // Bottom-Left

        // Back Curve (Concave)
        // Curves inward to x = startX + 5
        (p as any).bezierVertex(startX + 5, h * 0.75, startX + 5, h * 0.25, startX, py);

    } else {
        // AND/NAND: Flat Back + Rounded Front
        p.vertex(0, py);
        p.vertex(bodyW * 0.5, py);
        (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
        p.vertex(0, h - py);
        p.vertex(0, py); // Close box
    }

    p.endShape(p.CLOSE);

    // Draw Negation Bubble
    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); 
        p.stroke(COLOR_COMPONENT_STROKE);
        p.circle(gateW - bubbleR, h / 2, bubbleR*2); // バブル位置調整
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke();
        p.fill('#1e293b');
        p.textSize(12);
        p.textStyle(p.BOLD);

        if (comp.type === ComponentType.INPUT_SWITCH) {
           const side = comp.icPortSide || 'right';
           if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else if (comp.type === ComponentType.OUTPUT_LED) {
           const side = comp.icPortSide || 'left';
           if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
           else if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
           else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
           else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
        } else {
           p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        }
        p.textAlign(p.CENTER, p.CENTER);
        p.textStyle(p.NORMAL);
      }
  }

  private static drawArrow(p: p5Types, x: number, y: number, side: PortSide, size: number) {
    p.push();
    p.translate(x, y);
    if (side === 'right') p.rotate(0);
    else if (side === 'bottom') p.rotate(p.HALF_PI);
    else if (side === 'left') p.rotate(p.PI);
    else if (side === 'top') p.rotate(-p.HALF_PI);

    p.triangle(-size, -size/2, 0, 0, -size, size/2);
    p.pop();
  }
}

import React, { useState, useRef, useEffect, useLayoutEffect } from 'react';
import { FunctionCircuit, CircuitComponent, Wire } from '../types';
import { LogicCanvasHandle } from '../components/LogicCanvas';

const LOCAL_STORAGE_KEY = 'logicflow_autosave_v1';
const LOCAL_STORAGE_ID_KEY = 'logicflow_active_id_v1';

export const useProjectManager = (canvasRef: React.RefObject<LogicCanvasHandle | null>) => {
  // -- State --
  const [functions, setFunctions] = useState<FunctionCircuit[]>(() => {
    try {
      const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      }
    } catch (e) { console.error(e); }
    return [{ id: 'main', name: 'Main Circuit', components: [], wires: [] }];
  });

  const [activeFunctionId, setActiveFunctionId] = useState<string>(() => {
    try {
        const savedId = localStorage.getItem(LOCAL_STORAGE_ID_KEY);
        if (savedId) return savedId;
    } catch(e) {}
    return 'main';
  });

  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [dataVersion, setDataVersion] = useState(0); // Used to force-refresh canvas on bulk updates

  // Refs for autosave callback access
  const functionsRef = useRef(functions);
  const activeIdRef = useRef(activeFunctionId);
  useEffect(() => { functionsRef.current = functions; }, [functions]);
  useEffect(() => { activeIdRef.current = activeFunctionId; }, [activeFunctionId]);

  // -- Validation --
  useLayoutEffect(() => {
    if (!functions.find(f => f.id === activeFunctionId)) {
        setActiveFunctionId(functions[0]?.id || 'main');
    }
  }, [functions, activeFunctionId]);

  // -- Helpers --
  const getLatestFunctionsState = (): FunctionCircuit[] => {
    let currentData = functionsRef.current;
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        currentData = currentData.map(f => 
            f.id === activeIdRef.current 
              ? { ...f, components: [...components], wires: [...wires] } 
              : f
        );
    }
    return currentData;
  };

  const persist = () => {
    const data = getLatestFunctionsState();
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, activeIdRef.current);
        setLastSaved(new Date());
    } catch (e) { console.error("Save failed", e); }
    // Optimistic update of local state if needed, but usually we just sync refs
    // setFunctions(data); 
  };

  // -- Autosave Effect --
  useEffect(() => {
    const interval = setInterval(persist, 5000);
    const handleVis = () => { if (document.hidden) persist(); };
    const handleUnload = () => { persist(); };

    document.addEventListener("visibilitychange", handleVis);
    window.addEventListener("beforeunload", handleUnload);

    return () => {
        clearInterval(interval);
        document.removeEventListener("visibilitychange", handleVis);
        window.removeEventListener("beforeunload", handleUnload);
        persist();
    };
  }, []);

  // -- Actions --

  const syncCanvasToState = () => {
      const updated = getLatestFunctionsState();
      setFunctions(updated);
      return updated;
  };

  const switchToFunction = (id: string) => {
    if (id === activeFunctionId) return;
    syncCanvasToState();
    setActiveFunctionId(id);
  };

  const addFunction = (name: string) => {
    const current = syncCanvasToState();
    const newId = crypto.randomUUID();
    const newFunc: FunctionCircuit = { id: newId, name, components: [], wires: [] };
    const next = [...current, newFunc];
    setFunctions(next);
    setActiveFunctionId(newId);
    persist();
  };

  const deleteFunction = (id: string) => {
    if (id === 'main') return;
    const next = functions.filter(f => f.id !== id);
    setFunctions(next);
    if (activeFunctionId === id) setActiveFunctionId('main');
    persist();
  };

  const importData = (data: any, isFullProject: boolean) => {
      if (isFullProject) {
        setFunctions(data);
        setActiveFunctionId(data[0].id);
        setDataVersion(v => v + 1);
      } else {
        const current = getLatestFunctionsState();
        setFunctions([...current, data]);
      }
      persist();
  };

  const clearData = () => {
    localStorage.removeItem(LOCAL_STORAGE_KEY);
    localStorage.removeItem(LOCAL_STORAGE_ID_KEY);
    setFunctions([{ id: 'main', name: 'Main Circuit', components: [], wires: [] }]);
    setActiveFunctionId('main');
    setDataVersion(v => v + 1);
  };

  return {
      functions,
      activeFunctionId,
      activeFunction: functions.find(f => f.id === activeFunctionId) || functions[0],
      lastSaved,
      dataVersion,
      getLatestFunctionsState,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist // Quick save
  };
};
